protected async retrieveFts(
  args: RetrievalPipelineRunArguments,
  n: number,
): Promise<Chunk[]> {
  if (args.query.trim() === "") {
    return [];
  }

  const tokens = this.getCleanedTrigrams(args.query).join(" OR ");

  return await this.ftsIndex.retrieve({
    n,
    text: tokens,
    tags: args.tags,
    directory: args.filterDirectory,
  });
}

